def cache_sim(capacity, ttl, ops):
    from collections import OrderedDict

    cache = OrderedDict()  # {key: (value, write_time)}
    results = []
    current_time = 0

    def is_expired(write_time, current_time):
        return current_time >= write_time + ttl

    def remove_expired():
        # Remove all expired entries
        expired_keys = [key for key, (value, write_time) in cache.items() 
                       if is_expired(write_time, current_time)]
        for key in expired_keys:
            del cache[key]

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op
            current_time = t
            remove_expired()

            # Remove key if it exists (to reposition it)
            if key in cache:
                del cache[key]
            # If cache is full, remove LRU (first item in OrderedDict)
            elif len(cache) >= capacity:
                cache.popitem(last=False)

            # Add the new entry (becomes most recent)
            cache[key] = (value, t)

        elif op[0] == 'get':
            _, t, key = op
            current_time = t
            remove_expired()

            if key in cache:
                value, write_time = cache[key]
                # Move to end (most recently used)
                del cache[key]
                cache[key] = (value, write_time)
                results.append(value)
            else:
                results.append(-1)

    return results

